<!-- Generated by Trae Work -->
<!--
  移动端悬浮药丸底栏 v2
  - iOS 26 Liquid Glass 风格
  - JS动态测量tab位置，滑动指示器永远精确不错位
  - spring弹性动效 cubic-bezier(0.34, 1.56, 0.64, 1)
  - 无完整边框，只有顶部高光
-->
<template>
  <nav class="tabbar" v-if="isMobile">
    <div class="tabbar-inner" ref="barRef">
      <!-- 滑动药丸指示器：用JS动态测量位置，永远精确 -->
      <div
        class="tab-pill"
        :style="{ transform: `translateX(${pill.x}px)`, width: `${pill.w}px`, height: `${pill.h}px` }"
      />
      <button
        v-for="(t, i) in tabs"
        :key="t.to"
        class="tab"
        :class="{ on: activeIndex === i }"
        :ref="el => setTabRef(el, i)"
        @click="go(t.to)"
      >
        <span class="t-ic" v-html="t.ic"></span>
        <span class="t-lb">{{ t.lb }}</span>
      </button>
    </div>
  </nav>
</template>

<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, nextTick, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useUserStore } from '@/store/user'

const route = useRoute()
const router = useRouter()
const user = useUserStore()
const barRef = ref<HTMLElement | null>(null)
const tabRefs = ref<(HTMLElement | null)[]>([])

const setTabRef = (el: any, i: number) => {
  if (el) tabRefs.value[i] = el
}

const allTabs = [
  { to: '/', lb: '首页', ic: '🏠', roles: ['SUPER_ADMIN','TEACHER','STUDENT'] },
  { to: '/subjects', lb: '科目', ic: '📚', roles: ['SUPER_ADMIN','TEACHER','STUDENT'] },
  { to: '/guide', lb: '指南', ic: '🧭', roles: ['SUPER_ADMIN','TEACHER','STUDENT'] },
  { to: '/profile', lb: '我的', ic: '👤', roles: ['SUPER_ADMIN','TEACHER','STUDENT'] },
  { to: '/admin', lb: '管理', ic: '⚙️', roles: ['SUPER_ADMIN','TEACHER'] },
]

const tabs = computed(() => allTabs.filter(t => t.roles.includes((user as any).role || 'STUDENT')))

const activeIndex = computed(() => {
  const p = route.path
  const idx = tabs.value.findIndex(t => {
    if (t.to === '/') return p === '/'
    return p.startsWith(t.to)
  })
  return idx >= 0 ? idx : 0
})

// 药丸指示器位置和大小
const pill = ref({ x: 0, w: 0, h: 40 })

// 测量并更新药丸位置
const measurePill = () => {
  if (!barRef.value) return
  const bar = barRef.value
  const activeEl = tabRefs.value[activeIndex.value]
  if (!activeEl) return

  const barRect = bar.getBoundingClientRect()
  const elRect = activeEl.getBoundingClientRect()

  // 计算在bar内的相对位置
  const x = elRect.left - barRect.left
  // 药丸宽度比tab稍小，留出内边距
  const w = Math.max(48, elRect.width - 12)
  // 居中偏移
  const offsetX = (elRect.width - w) / 2

  pill.value = {
    x: x + offsetX,
    w: w,
    h: 40
  }
}

// 监听路由变化更新药丸
watch(activeIndex, () => {
  nextTick(() => measurePill())
})

let ro: ResizeObserver | null = null

const isMobile = ref(false)
const check = () => { isMobile.value = window.innerWidth <= 768 }

onMounted(() => {
  check()
  window.addEventListener('resize', () => {
    check()
    measurePill()
  })
  nextTick(() => {
    measurePill()
    if (window.ResizeObserver && barRef.value) {
      ro = new ResizeObserver(() => measurePill())
      ro.observe(barRef.value)
      tabRefs.value.forEach(el => el && ro?.observe(el))
    }
  })
})

onUnmounted(() => {
  window.removeEventListener('resize', check)
  window.removeEventListener('resize', measurePill)
  ro?.disconnect()
})

function go(to: string) { router.push(to) }
</script>

