    0 20px 48px -20px rgba(0, 0, 0, 0.08);
}

/* 滑动药丸指示器：Liquid Glass 风格金色磨砂药丸 */
.tab-pill {
  position: absolute;
  top: 50%;
  left: 6px;
  height: 40px;
  border-radius: 20px;
  background: linear-gradient(145deg, rgba(var(--zg-primary-rgb, 201, 168, 76), 0.15), rgba(var(--zg-accent-rgb, 232, 213, 163), 0.12));
  box-shadow:
    inset 0 0.5px 0.5px rgba(255, 255, 255, 0.8),
    inset 0 0 0 0.5px rgba(var(--zg-primary-rgb, 201, 168, 76), 0.2),
    0 1px 3px rgba(var(--zg-primary-rgb, 201, 168, 76), 0.10);
  transform: translateX(0);
  transition: transform 0.45s cubic-bezier(0.34, 1.56, 0.64, 1),
              width 0.45s cubic-bezier(0.34, 1.56, 0.64, 1);
  margin-top: -20px;
  z-index: 0;
  pointer-events: none;
}

.tab {
  position: relative;
  z-index: 1;
  flex: 1;
  min-width: 0;
  height: 50px;
  border: none;
  background: transparent;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  color: var(--zg-text-dim, #6b7280);
  transition: color 0.3s cubic-bezier(0.22, 1, 0.36, 1),
              transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  padding: 0;
  font-family: inherit;
}

.t-ic {
  font-size: 20px;
  line-height: 1;
  filter: grayscale(0.3);
  transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1),
              filter 0.3s ease;
}

.t-lb {
  font-size: 10px;
  font-weight: 500;
  line-height: 1;
  letter-spacing: 0.02em;
  transition: font-weight 0.3s ease, color 0.3s ease;
}

.tab.on {
  color: var(--zg-primary, #c9a84c);
}

.tab.on .t-ic {
  filter: grayscale(0);
  transform: scale(1.15) translateY(-1px);
}

.tab.on .t-lb {
  font-weight: 700;
}

.tab:active {
  transform: scale(0.92);
}

/* 深色模式适配 */
